import type { ProductRating } from '../salla-review-factors-tags/interfaces';
export interface AttachmentMediaSource {
    images?: string[];
    videos?: string[];
    product?: {
        id?: number | string;
    };
}
export interface OrderItemRating extends AttachmentMediaSource {
    id?: number | string;
    stars?: number;
    content?: string;
    is_pending?: boolean;
    can_update?: boolean;
}
export type ProductRatingMediaSource = ProductRating & AttachmentMediaSource;
export interface OrderItem {
    id?: number | string;
    product?: {
        id?: number | string;
    };
    rating?: OrderItemRating | null;
}
export interface OrderResponse {
    items?: OrderItem[];
    rating?: {
        product?: unknown;
        products?: unknown;
    };
}
